program.reference:
# 辗转相除法
def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)
# 菜品数量为n
n = int(input())
# 每一道菜品的美味度
arr = list(map(int, input().split()))
ans = 0
for i in range(n):
    for j in range(i + 1, n):
        if gcd(arr[i], arr[j]) == 1:
            ans = max(ans, arr[i] + arr[j])
assert ans != 0
print(ans)
